#!/usr/bin/env python3
"""sen0414_lineage_rule5fix v1_0_0 - ONE new register file: repairs the L3 violation the validation of 2.379.0 printed for ST4_Rule5. The story was registered (2.367.0) as a mover of the papers-built objective Obj4_PapersBuilt; closing it needs a reading of that objective dated at or after the finish and, because the number does not change, a retrospective finding (the same repair as for ST4_Leak). No claim is changed."""
import os, sys, re
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now()
i = t.index("\nex:ST4_Rule5 a backlog:Story"); fin = re.search(r'finishedAt "([^"]+)Z"', t[i:t.find("\nex:", i + 5)]).group(1)
add = ['ex:Obs50c_Obj4_PapersBuilt a backlog:MetricObservation ; rdfs:label "Reading when the rule 5 item was closed"@en ;\n    backlog:observesMetric ex:Met4_Papers ; backlog:observationFor ex:Obj4_PapersBuilt ; backlog:hasObservedValue "2"^^xsd:decimal ; backlog:observedAt "%sZ"^^xsd:dateTime ;\n    backlog:hasObservationMethod "Unchanged at 2 (the papers exist); the rule 5 item cannot raise this count." .\n' % fin,
       'ex:Finding_Rule5Mover a backlog:RetrospectiveFinding ;\n    rdfs:label "The rule 5 item was recorded as a mover of the papers-built metric, which it cannot move"@en ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:relatesToWorkItem ex:ST4_Rule5 ; backlog:hasFindingScope backlog:Scope_Methodology ;\n    backlog:hasRootCause %s ;\n    backlog:hasRemedy %s .\n' % (W.lit("When ST4_Rule5 was registered (2.367.0) it was attached to the existing objective Obj4_PapersBuilt only because a story needs an objective; its work (a printed rule inside the margin) does not change the number of papers. The reading stays at 2, as it must."), W.lit("ST4_Rule5 now pursues its own objective Obj6_Rule5Wraps (from 1 cut-off line to 0), which it moved; the earlier mover assertion on Obj4_PapersBuilt stays as recorded (append-only) and is answered by this finding. A story registered for a repair gets its own measurable objective at registration."))]
print(os.path.basename(W.write_new(src, t + "\n" + "".join(add), "Exam revision: ST4_Rule5 closure completed (reading of the papers-built objective and its finding).")))
